@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="supplier.catalog.enabled=false")
class AuditBootNetworkProbeTests {
    @Container @ServiceConnection static final PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
    static final AtomicInteger started=new AtomicInteger(),closed=new AtomicInteger(),completed=new AtomicInteger();
    static volatile boolean hold;
    static volatile Sinks.One<String> release=Sinks.one();
    static final DisposableServer upstream=HttpServer.create().host("127.0.0.1").port(0).handle((req,res)->{
        started.incrementAndGet();
        if(hold) {
            req.withConnection(c->c.onDispose().doFinally(s->closed.incrementAndGet()).subscribe());
            String body=req.uri().startsWith("/a/")?"{\"items\":[]}":"{\"resultCode\":\"0000\",\"data\":{\"items\":[]}}";
            return res.header("Content-Type","application/json").sendString(release.asMono().thenReturn(body)).then().doFinally(s->completed.incrementAndGet());
        }
        return res.header("Content-Type","application/json").sendString(Mono.just("{\"resultCode\":\"E503\",\"data\":null}")).then();
    }).bindNow();
    @DynamicPropertySource static void config(DynamicPropertyRegistry r) {
        r.add("supplier.a.base-url",()->"http://127.0.0.1:"+upstream.port());
        r.add("supplier.b.base-url",()->"http://127.0.0.1:"+upstream.port());
    }
    @LocalServerPort int port;
    @MockitoBean ActiveCatalogMappingReader reader;
    @Autowired SupplierBSearchClient client;
    @Autowired MeterRegistry metrics;
    @BeforeEach void reset() {
        hold=false;release=Sinks.one();started.set(0);closed.set(0);completed.set(0);metrics.clear();
        when(reader.findAllActive()).thenReturn(List.of(
            new ActiveCatalogMapping(1,Supplier.SUPPLIER_A,"P1","One",101,"R1","Room"),
            new ActiveCatalogMapping(2,Supplier.SUPPLIER_B,"P2","Two",201,"R2","Room")));
    }
    @AfterAll static void stop(){upstream.disposeNow();}
    void await(java.util.function.BooleanSupplier condition) throws Exception {
        long deadline=System.nanoTime()+Duration.ofSeconds(3).toNanos();
        while(!condition.getAsBoolean()&&System.nanoTime()<deadline)Thread.sleep(10);
        assertThat(condition.getAsBoolean()).isTrue();
    }
    @Test void customerDisconnectDoesNotImmediatelyCancelUpstream() throws Exception {
        hold=true;
        Socket socket=new Socket("127.0.0.1",port);
        try {
            socket.getOutputStream().write(("GET /api/v1/stays/search?checkIn=2026-10-01&checkOut=2026-10-04&adults=2 HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));
            socket.getOutputStream().flush();
            await(()->started.get()==2);
            socket.setSoLinger(true,0);socket.close();
            Thread.sleep(300);
            assertThat(completed.get()).isZero();assertThat(closed.get()).isZero();
            System.out.println("NETAUDIT customerDisconnect: 300ms after TCP reset upstreamRequests=2 peerClosed=0 completed=0");
        } finally {socket.close();release.tryEmitValue("go");}
        await(()->completed.get()==2);
    }
    @Test void bodyFailureIsNotVisibleAsFailureInGenericHttpMetric() {
        var req=new SupplierSearchRequest(Supplier.SUPPLIER_B,new SearchCriteria(LocalDate.of(2026,10,1),LocalDate.of(2026,10,4),2,0),
            List.of(new SupplierSearchRequest.PropertyMapping(2,"P2",List.of(new SupplierSearchRequest.RoomTypeMapping(201,"R2")))));
        Throwable error=catchThrowable(()->client.search(req).block());
        assertThat(error).isInstanceOfSatisfying(SupplierIntegrationException.class,e->assertThat(e.getFailureType()).isEqualTo(SupplierFailureType.UNAVAILABLE));
        var meters=metrics.getMeters().stream().filter(m->m.getId().getName().contains("http.client")||m.getId().getName().contains("supplier")).map(m->m.getId().toString()).toList();
        System.out.println("NETAUDIT bodyFailureMetric: application=UNAVAILABLE meters="+meters);
        System.out.println("NETAUDIT runtime reactorNetty="+reactor.netty.http.client.HttpClient.class.getPackage().getImplementationVersion()+" maxConnections="+reactor.netty.http.HttpResources.get().maxConnections()+" poolAcquireDefaultMs="+reactor.netty.resources.ConnectionProvider.DEFAULT_POOL_ACQUIRE_TIMEOUT);
    }
}

package com.supplierhub.supplier.common;
import static org.assertj.core.api.Assertions.*;
