import java.util.*;
import java.util.stream.*;
import org.junit.jupiter.api.Test;
import reactor.core.publisher.Mono;
import com.supplierhub.catalog.application.*;
import com.supplierhub.catalog.domain.Supplier;
import com.supplierhub.search.application.*;
import com.supplierhub.search.domain.*;
import com.supplierhub.search.api.StaySearchResponse;

class AuditMemoryProbeTests {
    static final Supplier A=Supplier.SUPPLIER_A,B=Supplier.SUPPLIER_B;
    long[] size(Object root) throws Exception {return (long[])Class.forName("audit.SizeAgent").getMethod("size",Object.class).invoke(null,root);}
    SearchCriteria criteria(int nights) {return new SearchCriteria(LocalDate.of(2026,10,1),LocalDate.of(2026,10,1).plusDays(nights),2,0);}
    IntegratedSearchResult result(Supplier supplier,int nights) {
        var criteria=criteria(nights);
        var items=IntStream.rangeClosed(1,1000).mapToObj(i->{
            Price price=supplier==A?Price.fromNightlyPrices(IntStream.range(0,nights).mapToObj(d->new NightlyPrice(criteria.checkIn().plusDays(d),Money.of("KRW",10000),Money.of("KRW",1000))).toList()):Price.totalOnly(Money.of("KRW",11000L*nights));
            var inventory=IntStream.range(0,nights).mapToObj(d->new DailyInventory(criteria.checkIn().plusDays(d),2)).toList();
            var offer=Offer.createAvailable(i,i,supplier,2,false,price,criteria,inventory).orElseThrow();
            return new SearchOffer(offer,"Property "+i,"Room "+i);
        }).toList();
        return new IntegratedSearchResult(SearchStatus.COMPLETE,List.of(new SupplierSearchOutcome(supplier,SupplierSearchStatus.SUCCESS,items,0,0,List.of())));
    }
    @Test void measuresReachableOfferGraphAndPublicResponse() throws Exception {
        for(Supplier supplier:List.of(A,B))for(int nights:List.of(1,30)) {
            var result=result(supplier,nights);var graph=size(result);var response=size(StaySearchResponse.from(criteria(nights),result));
            System.out.println("NETAUDIT graph supplier="+supplier+" offers=1000 nights="+nights+" applicationBytes="+graph[0]+" applicationObjects="+graph[1]+" responseBytes="+response[0]+" responseObjects="+response[1]);
            assertThat(response[0]).isGreaterThan(0);
        }
    }
    @Test void measuresCatalogAndPerSearchAllocationWithNoOffers() throws Exception {
        var mx=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();
        assertThat(mx.isThreadAllocatedMemorySupported()).isTrue();mx.setThreadAllocatedMemoryEnabled(true);
        for(int properties:List.of(1000,6000)) {
            List<ActiveCatalogMapping> rows=IntStream.rangeClosed(1,properties).boxed().flatMap(i->IntStream.rangeClosed(1,5).mapToObj(j->
                new ActiveCatalogMapping(i,A,"P"+i,"Property "+i,i*100L+j,"R"+j,"Room "+j))).toList();
            var p=new SupplierIntegrationProperties(new SupplierIntegrationProperties.Endpoint(true,URI.create("http://localhost"),"test"),new SupplierIntegrationProperties.Endpoint(false,URI.create("http://localhost"),"test"),
                new SupplierIntegrationProperties.Catalog(true,Duration.ofSeconds(1),Duration.ofSeconds(2),Duration.ofSeconds(3),0,Duration.ofMillis(1),Duration.ZERO,Duration.ofMinutes(10),10,0.5),
                new SupplierIntegrationProperties.Search(Duration.ofSeconds(1),Duration.ofSeconds(2),Duration.ofSeconds(3),Duration.ofSeconds(10),4));
            SupplierSearchClient client=new SupplierSearchClient(){
                public Supplier supplier(){return A;}
                public Mono<SupplierSearchResult> search(SupplierSearchRequest request){return Mono.just(new SupplierSearchResult(A,List.of(),0,0));}
            };
            var service=new IntegratedSearchService(()->rows,List.of(client),p);
            for(int warm=0;warm<3;warm++)service.search(criteria(1));
            List<Long> allocations=new ArrayList<>();List<Long> nanos=new ArrayList<>();
            for(int run=0;run<5;run++) {
                long before=mx.getThreadAllocatedBytes(Thread.currentThread().threadId());long start=System.nanoTime();
                var result=service.search(criteria(1));
                nanos.add(System.nanoTime()-start);allocations.add(mx.getThreadAllocatedBytes(Thread.currentThread().threadId())-before);
                assertThat(result.offers()).isEmpty();assertThat(result.status()).isEqualTo(SearchStatus.COMPLETE);
            }
            long[] graph=size(rows);
            System.out.println("NETAUDIT catalog properties="+properties+" rooms="+(properties*5)+" reachableBytes="+graph[0]+" objects="+graph[1]+" emptySearchAllocatedBytes="+allocations+" elapsedNanos="+nanos);
        }
    }
}

package com.supplierhub.supplier.common;
import static org.assertj.core.api.Assertions.*;
import java.net.URI;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.BiFunction;
import java.util.stream.*;
import org.junit.jupiter.api.*;
import org.reactivestreams.Publisher;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.*;
import reactor.netty.*;
import reactor.netty.http.server.*;
import com.supplierhub.catalog.application.*;
import com.supplierhub.catalog.domain.Supplier;
import com.supplierhub.search.application.*;
import com.supplierhub.search.domain.SearchCriteria;
import com.supplierhub.supplier.suppliera.*;
import com.supplierhub.supplier.supplierb.*;

class AuditNetworkProbeTests {
    static final Supplier A=Supplier.SUPPLIER_A,B=Supplier.SUPPLIER_B;
    static final SearchCriteria CRITERIA=new SearchCriteria(LocalDate.of(2026,10,1),LocalDate.of(2026,10,4),2,0);
    static final String EMPTY_A="{\"items\":[]}", EMPTY_B="{\"resultCode\":\"0000\",\"data\":{\"items\":[]}}";
    DisposableServer serverA,serverB;
    volatile BiFunction<HttpServerRequest,HttpServerResponse,Publisher<Void>> handlerA,handlerB;
    AtomicInteger callsA=new AtomicInteger(),callsB=new AtomicInteger(),activeA=new AtomicInteger(),activeB=new AtomicInteger(),peakA=new AtomicInteger(),peakB=new AtomicInteger();
    @BeforeEach void start() {
        handlerA=(req,res)->json(res,EMPTY_A); handlerB=(req,res)->json(res,EMPTY_B);
        serverA=HttpServer.create().host("127.0.0.1").port(0).handle((req,res)->observe(req,res,true)).bindNow();
        serverB=HttpServer.create().host("127.0.0.1").port(0).handle((req,res)->observe(req,res,false)).bindNow();
    }
    Publisher<Void> observe(HttpServerRequest req,HttpServerResponse res,boolean isA) {
        var active=isA?activeA:activeB; var peak=isA?peakA:peakB;
        (isA?callsA:callsB).incrementAndGet(); peak.accumulateAndGet(active.incrementAndGet(),Math::max);
        return Mono.from((isA?handlerA:handlerB).apply(req,res)).doFinally(sig->active.decrementAndGet());
    }
    Publisher<Void> json(HttpServerResponse res,String body) { return res.header("Content-Type","application/json").sendString(Mono.just(body)).then(); }
    @AfterEach void stop() { serverA.disposeNow();serverB.disposeNow(); }
    void await(java.util.function.BooleanSupplier condition,long millis) throws Exception {
        long deadline=System.nanoTime()+Duration.ofMillis(millis).toNanos();
        while(!condition.getAsBoolean()&&System.nanoTime()<deadline)Thread.sleep(10);
        assertThat(condition.getAsBoolean()).isTrue();
    }
    SupplierIntegrationProperties settings(Duration response,Duration call,Duration overall,int concurrency) {
        return new SupplierIntegrationProperties(
            new SupplierIntegrationProperties.Endpoint(true,URI.create("http://127.0.0.1:"+serverA.port()),"test-a"),
            new SupplierIntegrationProperties.Endpoint(true,URI.create("http://127.0.0.1:"+serverB.port()),"test-b"),
            new SupplierIntegrationProperties.Catalog(true,Duration.ofMillis(500),response,call,2,Duration.ofMillis(10),Duration.ZERO,Duration.ofMinutes(10),10,0.5),
            new SupplierIntegrationProperties.Search(Duration.ofMillis(500),response,call,overall,concurrency));
    }
    SupplierASearchClient a(SupplierIntegrationProperties p) { return new SupplierASearchClient(new SupplierClientConfiguration().supplierASearchWebClient(WebClient.builder(),p),p); }
    SupplierBSearchClient b(SupplierIntegrationProperties p) { return new SupplierBSearchClient(new SupplierClientConfiguration().supplierBSearchWebClient(WebClient.builder(),p),p); }
    List<ActiveCatalogMapping> mappings(Supplier s,int count,int roomCount) {
        return IntStream.rangeClosed(1,count).boxed().flatMap(i -> IntStream.rangeClosed(1,roomCount).mapToObj(j ->
            new ActiveCatalogMapping((s==A?0:100000)+i,s,"P"+i,"Property "+i,(s==A?0:10000000)+i*100L+j,"R"+j,"Room "+j))).toList();
    }
    SupplierSearchRequest request(Supplier s,int count,int roomCount,SearchCriteria criteria) {
        return new SupplierSearchRequest(s,criteria,IntStream.rangeClosed(1,count).mapToObj(i ->
            new SupplierSearchRequest.PropertyMapping(i,"P"+i,IntStream.rangeClosed(1,roomCount).mapToObj(j ->
                new SupplierSearchRequest.RoomTypeMapping(i*100L+j,"R"+j)).toList())).toList());
    }
    IntegratedSearchService service(int countA,int countB,SupplierIntegrationProperties p) {
        List<ActiveCatalogMapping> rows=Stream.concat(mappings(A,countA,1).stream(),mappings(B,countB,1).stream()).toList();
        return new IntegratedSearchService(()->rows,List.of(a(p),b(p)),p);
    }
    void emit(String value) { System.out.println("NETAUDIT "+value); }
    String causes(Throwable t) { List<String> all=new ArrayList<>();for(Throwable c=t;c!=null;c=c.getCause())all.add(c.getClass().getSimpleName());return String.join(" -> ",all); }

    @Test void concurrencyLimitMultipliesAcrossCustomerSearches() throws Exception {
        Sinks.One<String> gateA=Sinks.one(),gateB=Sinks.one();
        handlerA=(req,res)->res.header("Content-Type","application/json").sendString(gateA.asMono()).then();
        handlerB=(req,res)->res.header("Content-Type","application/json").sendString(gateB.asMono()).then();
        var p=settings(Duration.ofSeconds(6),Duration.ofSeconds(7),Duration.ofSeconds(8),4);
        var service=service(200,200,p);
        try(var pool=Executors.newFixedThreadPool(8)) {
            List<Future<IntegratedSearchResult>> futures=IntStream.range(0,8).mapToObj(i -> pool.submit(()->service.search(CRITERIA))).toList();
            try { await(()->callsA.get()==32&&callsB.get()==32,4000); }
            finally { gateA.tryEmitValue(EMPTY_A);gateB.tryEmitValue(EMPTY_B); }
            for(var future:futures)assertThat(future.get(5,TimeUnit.SECONDS).status()).isEqualTo(SearchStatus.COMPLETE);
            assertThat(peakA.get()).isEqualTo(32);assertThat(peakB.get()).isEqualTo(32);
            emit("customerConcurrency=8 configuredPerRequest=4 upstreamPeakA="+peakA+" upstreamPeakB="+peakB+" totalCalls=64");
        }
    }

    @Test void batchesUseFiftyPropertiesAndAtMostFourCallsPerSupplier() {
        List<Integer> sizes=new CopyOnWriteArrayList<>();
        handlerA=(req,res)->{
            String codes=req.uri().split("hotelCodes=")[1].split("&")[0]; sizes.add(codes.split(",|%2C").length);
            return res.header("Content-Type","application/json").sendString(Mono.delay(Duration.ofMillis(100)).thenReturn(EMPTY_A)).then();
        };
        handlerB=(req,res)->res.header("Content-Type","application/json").sendString(Mono.delay(Duration.ofMillis(100)).thenReturn(EMPTY_B)).then();
        var result=service(251,251,settings(Duration.ofSeconds(2),Duration.ofSeconds(3),Duration.ofSeconds(5),4)).search(CRITERIA);
        assertThat(result.status()).isEqualTo(SearchStatus.COMPLETE);
        assertThat(callsA.get()).isEqualTo(6);assertThat(callsB.get()).isEqualTo(6);
        assertThat(peakA.get()).isLessThanOrEqualTo(4);assertThat(peakB.get()).isLessThanOrEqualTo(4);
        assertThat(sizes).containsExactlyInAnyOrder(50,50,50,50,50,1);
        emit("batching 251 properties: callsA=6 callsB=6 peakA="+peakA+" peakB="+peakB+" sizes="+sizes);
    }

    @Test void overallDeadlineClosesActiveSocketAndNeverStartsQueuedBatch() throws Exception {
        AtomicBoolean hangingClosed=new AtomicBoolean();
        handlerA=(req,res)->{
            if(callsA.get()==1)return json(res,"{\"items\":["+itemA(1,1,3)+"]}");
            req.withConnection(conn->conn.onDispose().doFinally(sig->hangingClosed.set(true)).subscribe());
            return res.sendString(Mono.never()).then();
        };
        var p=settings(Duration.ofSeconds(3),Duration.ofSeconds(4),Duration.ofMillis(700),1);
        var result=service(101,1,p).search(CRITERIA);
        assertThat(result.status()).isEqualTo(SearchStatus.PARTIAL);assertThat(result.offers()).hasSize(1);
        assertThat(callsA.get()).isEqualTo(2);await(hangingClosed::get,2000);
        handlerA=(req,res)->json(res,EMPTY_A);
        assertThat(a(p).search(request(A,1,1,CRITERIA)).block().offers()).isEmpty();
        emit("overallDeadline: completedOffer=1 sentA=2/3 queuedBatchNotSent=true peerSocketClosed=true recoverySuccess=true");
    }

    @Test void responseAndCallTimeoutClosePeerConnectionsWithoutRetry() throws Exception {
        for(boolean isA:List.of(true,false)) {
            for(boolean responseFirst:List.of(true,false)) {
                AtomicBoolean closed=new AtomicBoolean();
                BiFunction<HttpServerRequest,HttpServerResponse,Publisher<Void>> never=(req,res)->{
                    req.withConnection(conn->conn.onDispose().doFinally(sig->closed.set(true)).subscribe());
                    return res.sendString(Mono.never()).then();
                };
                if(isA)handlerA=never;else handlerB=never;
                var p=settings(responseFirst?Duration.ofMillis(180):Duration.ofSeconds(2),responseFirst?Duration.ofSeconds(3):Duration.ofMillis(250),Duration.ofSeconds(5),4);
                int before=(isA?callsA:callsB).get(); long start=System.nanoTime();
                Throwable error=catchThrowable(()->(isA?a(p):b(p)).search(request(isA?A:B,1,1,CRITERIA)).block());
                assertThat(error).isInstanceOfSatisfying(SupplierIntegrationException.class,e->assertThat(e.getFailureType()).isEqualTo(SupplierFailureType.TIMEOUT));
                await(closed::get,2000);assertThat((isA?callsA:callsB).get()-before).isEqualTo(1);
                emit("timeout supplier="+(isA?"A":"B")+" kind="+(responseFirst?"response":"call")+" elapsedMs="+Duration.ofNanos(System.nanoTime()-start).toMillis()+" peerClosed=true requests=1 causes="+causes(error));
            }
        }
    }

    @Test void observesTransportRetryAfterAbruptPeerDisconnect() {
        handlerA=(req,res)->{req.withConnection(Connection::dispose);return Mono.never();};
        var p=settings(Duration.ofSeconds(1),Duration.ofSeconds(2),Duration.ofSeconds(3),4);
        Throwable error=catchThrowable(()->a(p).search(request(A,1,1,CRITERIA)).block());
        assertThat(error).isNotNull();
        emit("abruptDisconnect supplier=A requests="+callsA+" causes="+causes(error));
    }

    String itemA(int property,int room,int nights) {
        String days=IntStream.range(0,nights).mapToObj(d->"{\"date\":\""+LocalDate.of(2026,10,1).plusDays(d)+"\",\"remainingRooms\":2,\"nightlyRate\":10000,\"taxAmount\":1000}").collect(Collectors.joining(","));
        return "{\"hotelCode\":\"P"+property+"\",\"roomTypeCode\":\"R"+room+"\",\"maxOccupancy\":2,\"breakfastIncluded\":false,\"currency\":\"KRW\",\"dailyRates\":["+days+"]}";
    }
    @Test void observesLargeValidSearchResponseLimit() {
        String items=IntStream.rangeClosed(1,50).boxed().flatMap(i->IntStream.rangeClosed(1,5).mapToObj(j->itemA(i,j,30))).collect(Collectors.joining(","));
        String body="{\"items\":["+items+"]}"; handlerA=(req,res)->json(res,body);
        var criteria=new SearchCriteria(LocalDate.of(2026,10,1),LocalDate.of(2026,10,31),2,0);
        var p=settings(Duration.ofSeconds(2),Duration.ofSeconds(3),Duration.ofSeconds(5),4);
        Throwable error=catchThrowable(()->a(p).search(request(A,50,5,criteria)).block());
        assertThat(error).isNotNull();
        var rows=mappings(A,50,5);
        var integrated=new IntegratedSearchService(()->Stream.concat(rows.stream(),mappings(B,1,1).stream()).toList(),List.of(a(p),b(p)),p).search(criteria);
        emit("largeSearch bytes="+body.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+" causes="+causes(error)+" integrated="+integrated.status()+" failures="+integrated.supplierResults().getFirst().failureTypes());
    }

    @Test void observesLargeValidCatalogResponseLimit() {
        String body="{\"items\":["+IntStream.rangeClosed(1,3000).mapToObj(i->"{\"hotelCode\":\"P"+i+"\",\"hotelName\":\"Property "+i+"\",\"roomTypes\":[{\"roomTypeCode\":\"R\",\"roomTypeName\":\"Room\",\"maxOccupancy\":2}]}").collect(Collectors.joining(","))+"]}";
        handlerA=(req,res)->json(res,body);
        var p=settings(Duration.ofSeconds(2),Duration.ofSeconds(3),Duration.ofSeconds(5),4);
        var client=new SupplierACatalogClient(new SupplierClientConfiguration().supplierAWebClient(WebClient.builder(),p));
        Throwable error=catchThrowable(()->client.fetchCatalog().block());assertThat(error).isNotNull();
        emit("largeCatalog properties=3000 bytes="+body.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+" causes="+causes(error));
    }
}

package audit;
import java.lang.instrument.Instrumentation;
import java.lang.reflect.*;
import java.util.*;
public class SizeAgent {
    static Instrumentation instrumentation;
    public static void premain(String args,Instrumentation value) { instrumentation=value; }
    public static long[] size(Object root) throws Exception {
        IdentityHashMap<Object,Boolean> seen=new IdentityHashMap<>();ArrayDeque<Object> queue=new ArrayDeque<>();queue.add(root);
        long bytes=0,objects=0;
        while(!queue.isEmpty()) {
            Object object=queue.removeFirst();if(seen.put(object,Boolean.TRUE)!=null)continue;
            bytes+=instrumentation.getObjectSize(object);objects++;
            Class<?> type=object.getClass();
            if(type.isArray()) {if(!type.getComponentType().isPrimitive())for(Object value:(Object[])object)if(value!=null)queue.add(value);continue;}
            if(type.isEnum()||object instanceof Class<?>)continue;
            for(Class<?> c=type;c!=null;c=c.getSuperclass())for(Field f:c.getDeclaredFields()) {
                if(Modifier.isStatic(f.getModifiers())||f.getType().isPrimitive())continue;
                if(!f.trySetAccessible())throw new IllegalStateException("Cannot inspect "+f);
                Object value=f.get(object);if(value!=null)queue.add(value);
            }
        }
        return new long[]{bytes,objects};
    }
}

